    userToUpdate.passwordResetExpiresAt = undefined;
    userToUpdate.passwordResetRequestedAt = undefined;
    await saveDatabase(deps.db, deps.dbFilePath);
  }
  return null;
}
```

---

### 2. **Apply correct rate limiter to email verification confirm endpoint**
**File:** `server/src/routes/authRoutes.ts` (lines 59-61)

**Issue:** `/verify-email/confirm` uses `passwordResetLimiter` instead of `emailVerificationLimiter`, allowing ~20 attempts/hour instead of 5, weakening token brute-force protection.

**Fix:**
```typescript
// Line 59 - change from:
app.post('/api/v1/auth/verify-email/confirm', passwordResetLimiter, async (req, res) => {

// To:
app.post('/api/v1/auth/verify-email/confirm', emailVerificationLimiter, async (req, res) => {
  await handleEmailVerificationConfirm(req, res, deps);
});
```

**Note:** Also remove the duplicate inline implementation (lines 60-105) since it's now delegated to the handler.

---

## **Code Quality Issues**

### 3. **Create dedicated schema for email verification request**
**Files:**
- `server/src/routes/auth/schemas.ts` (add new schema)
- `server/src/routes/auth/handlers/emailVerification.ts` (line 23)

**Issue:** Email verification request handler uses `PasswordResetRequestSchema`, which is semantically confusing and reduces code clarity.

